/* ==UserStyle==
@name Pronouns.page Catppuccin
@namespace github.com/catppuccin/userstyles/styles/pronouns.page
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/pronouns.page
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/pronouns.page/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Apronouns.page
@description Soothing pastel theme for Pronouns.page
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("pronouns.page"),
  domain("pronomen.net"),
  domain("pronombr.es"),
  domain("pronomejo.net"),
  domain("fornovn.fo"),
  domain("pronoms.fr"),
  domain("pronom.it"),
  domain("zaimki.pl") {
  body:not([data-theme="dark"]) {
    #catppuccin(@lightFlavor);
  }

  body[data-theme="dark"],
  body[data-theme="dark"]:not(.reduced-colours) {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    background: @base;
    color: @text !important;

    --bs-body-color: @text;
    --bs-body-bg: @base;
    --bs-white-rgb: #lib.rgbify(@crust)[];
    --bs-primary-rgb: #lib.rgbify(@accent)[];
    --bs-secondary-rgb: #lib.rgbify(@overlay0)[];
    --bs-secondary-color: @subtext0;
    --bs-tertiary-bg: @crust;
    --bs-success-text-emphasis: @green;
    --bs-success-rgb: #lib.rgbify(@green)[];
    --bs-info-text-emphasis: @sapphire;
    --bs-warning-text-emphasis: @yellow;
    --bs-danger-text-emphasis: @red;
    --bs-danger-rgb: #lib.rgbify(@red)[];
    --bs-light-text-emphasis: @text;
    --bs-dark-text-emphasis: @subtext1;
    --bs-heading-color: @text;
    --bs-form-valid-color: @green;
    --bs-form-valid-border-color: @green;
    --bs-form-invalid-color: @red;
    --bs-form-invalid-border-color: @red;

    /* Buttons */

    .btn-primary {
      color: @crust;
      --bs-btn-bg: @accent;
    }

    .btn-primary,
    .btn-outline-primary {
      --bs-btn-hover-bg: @accent;
      --bs-btn-border-color: @accent;
      --bs-btn-hover-border-color: @accent;
      --bs-btn-active-bg: @accent;
      --bs-btn-active-border-color: @accent;
      --bs-btn-disabled-color: @accent;
      --bs-btn-disabled-bg: darken(@accent, 5%);
      --bs-btn-disabled-border-color: @accent;
    }

    .btn-outline-primary {
      color: @text;

      &:hover {
        color: @crust;
      }
    }

    .btn-success {
      --bs-btn-color: @crust;
      --bs-btn-bg: @green;
      --bs-btn-border-color: @green;
      --bs-btn-hover-color: @crust;
      --bs-btn-hover-bg: darken(@green, 5%);
      --bs-btn-hover-border-color: darken(@green, 5%);
      --bs-btn-active-color: @crust;
      --bs-btn-active-bg: darken(@green, 5%);
      --bs-btn-active-border-color: darken(@green, 5%);
      --bs-btn-disabled-color: @text;
      --bs-btn-disabled-bg: @green;
      --bs-btn-disabled-border-color: @green;
    }

    .btn-outline-success {
      color: @green;

      &:hover {
        color: @crust;
      }

      --bs-btn-color: @green;
      --bs-btn-border-color: @green;
      --bs-btn-hover-color: @crust;
      --bs-btn-hover-bg: @green;
      --bs-btn-hover-border-color: @green;
      --bs-btn-active-color: @crust;
      --bs-btn-active-bg: @green;
      --bs-btn-active-border-color: @green;
      --bs-btn-disabled-color: @green;
      --bs-btn-disabled-border-color: @green;
    }

    .btn-outline-danger {
      --bs-btn-color: @red;
      --bs-btn-border-color: @red;
      --bs-btn-hover-color: @crust;
      --bs-btn-hover-bg: @red;
      --bs-btn-hover-border-color: @red;
      --bs-btn-active-color: @crust;
      --bs-btn-active-bg: @red;
      --bs-btn-active-border-color: @red;
      --bs-btn-disabled-color: @red;
      --bs-btn-disabled-border-color: @red;
    }

    .btn-secondary {
      --bs-btn-color: @text;
      --bs-btn-bg: @overlay0;
      --bs-btn-border-color: @overlay0;
      --bs-btn-hover-color: @text;
      --bs-btn-hover-bg: @surface2;
      --bs-btn-hover-border-color: @surface2;
      --bs-btn-active-color: @text;
      --bs-btn-active-bg: @surface2;
      --bs-btn-active-border-color: @surface2;
      --bs-btn-disabled-color: @text;
      --bs-btn-disabled-bg: @overlay0;
      --bs-btn-disabled-border-color: @overlay0;
    }

    .btn-outline-secondary {
      --bs-btn-color: @overlay0;
      --bs-btn-border-color: @overlay0;
      --bs-btn-hover-color: @text;
      --bs-btn-hover-bg: @overlay0;
      --bs-btn-hover-border-color: @overlay0;
      --bs-btn-active-color: @text;
      --bs-btn-active-bg: @overlay0;
      --bs-btn-active-border-color: @overlay0;
      --bs-btn-disabled-color: @overlay0;
      --bs-btn-disabled-border-color: @overlay0;
    }

    .btn-light {
      &,
      &:disabled,
      &.disabled {
        color: @text;
        background-color: @crust;
      }
    }
    .btn-dark,
    .btn-outline-dark:hover {
      color: @crust;
      background-color: @text;
    }
    .btn-outline-dark {
      color: @text;
    }

    .btn-square {
      background-color: @accent !important;
    }

    /* Inputs */

    .form-check-input:checked {
      background-color: @accent !important;
      border-color: @accent !important;
    }

    .form-control {
      color: @text;
      background-color: @mantle;
      border-color: @surface0;

      &:focus {
        box-shadow: 0 0 0 0.25rem fade(@accent, 50%);
      }
    }

    .dropdown-menu {
      color: @text;
      background-color: @mantle;
      border-color: @surface0;

      .dropdown-item {
        color: @text;

        &:hover,
        &:focus {
          background-color: @crust;
        }
      }
    }

    /* Date/calendar input */
    .dp__theme_dark, .dp__theme_light {
      --dp-primary-color: @accent;
      --dp-text-color: @text;
      --dp-hover-text-color: @text;
      --dp-background-color: @surface0;
      --dp-hover-color: @surface1;
      --dp-disabled-color: @surface2;
      --dp-icon-color: @subtext0;
      --dp-hover-icon-color: @subtext1;
      --dp-secondary-color: @subtext0;

      .dp__overlay_cell_active,
      .dp__active_date,
      .dp__range_end,
      .dp__range_start {
        color: @crust;
      }
    }

    /* Header */

    header .nav-item {
      color: @text !important;

      &:hover {
        color: @accent !important;
      }
    }

    .nav-custom:not(.nav-custom-start) .nav-item {
      border-color: @surface0;

      &:hover {
        border-bottom-color: @accent !important;
      }

      &.btn.active,
      &.btn:hover {
        border-bottom-color: @accent !important;
      }
    }

    .nav-custom-start .btn,
    .nav-custom .btn {
      border-inline-start-color: @surface2 !important;

      &:hover,
      &.active {
        color: lighten(@accent, 5%) !important;
        border-inline-start-color: @accent !important;
      }
    }

    .hamburger-menu .btn-hamburger {
      background-color: @crust !important;
      border-color: @surface0;
    }

    .card {
      background-color: @mantle;
    }

    /* Footer */

    .separator {
      > .mask::after {
        box-shadow: 0 0 10px @text;
      }

      > span {
        box-shadow: 0 2px 4px @text;
        background: @text;
        color: @crust;
      }
    }

    /* Calendar */

    .list-group-flare > :first-child {
      border-top-color: @accent !important;
    }
    .list-group-item {
      color: @text !important;
      background-color: @mantle !important;
      border-color: @surface0 !important;
    }
    .calendar > .day.day-event {
      border-color: @accent;

      &:hover {
        background-color: darken(@accent, 10%) !important;

        .day-number {
          color: @crust;
          text-shadow: none;
        }
      }

      &.day-event-1 {
        background-color: @accent;
        color: @crust;
      }
    }

    /* Dictionary */
    .page-link {
      color: @text;
      background-color: @crust;
      border-color: @surface0;
    }
    .page-item.active .page-link {
      color: @crust;
      background-color: @accent;
      border-color: @accent;
    }
    .page-item.disabled .page-link {
      color: @text;
      background-color: @base;
      border-color: @surface0;
    }
    table {
      --bs-table-color: @text !important;
      --bs-table-striped-color: @text !important;
      --bs-table-hover-color: @text !important;
      --bs-table-hover-bg: @surface1 !important;
      --bs-table-striped-bg: @surface0 !important;
    }

    /* Other */

    .bg-light {
      background-color: @mantle !important;
    }
    .bg-dark {
      background-color: @text !important;
    }
    .bg-white {
      background-color: @crust !important;
    }
    .text-dark {
      color: @text !important;
    }
    .colour-default {
      color: @text !important;
    }
    .colour-pink, .text-primary {
      color: @accent !important;
    }
    .colour-orange {
      color: @peach !important;
    }
    .colour-red {
      color: @red !important;
    }
    .colour-grey {
      color: @overlay2 !important;
    }

    .alert-light {
      background-color: @surface2;
      color: @text;
    }
    .alert-info {
      background-color: fade(@sapphire, 30%);
      border-color: @sapphire;
      color: @text;
    }

    .nav-pills {
      --bs-nav-pills-link-active-bg: @accent;
      --bs-nav-pills-link-active-color: @crust;
    }

    .badge {
      --bs-badge-color: @text;
    }

    .border {
      border-color: @surface0 !important;
    }

    a {
      color: @accent;

      &:not(.nav-link.active):hover {
        color: lighten(@accent, 5%);
      }
    }

    code {
      color: @crust;
      background-color: @accent;
      border-color: transparent;
    }

    /* Share QR code */
    [fill="#ff95bb"] {
      fill: @accent;
    }

    mark,
    .mark {
      background-color: fade(@yellow, 50%);
      color: @text;
    }
  }
}

